  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useMemo } from 'react';
  4→import { HeroReel } from '@/components/HeroReel';
  5→import { LadderGrid } from '@/components/LadderGrid';
  6→import { usePerception } from '@/lib/perception/context';
  7→import { projects } from '@/lib/projects';
  8→import { ProjectAdapter } from '@/lib/perception/adapter';
  9→import { useIsMobile } from '@/lib/hooks/useIsMobile';
 10→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
 11→
 12→export default function HomePage() {
 13→  // Get perception state from context (sensor runs in PerceptionLayer)
 14→  const { archetype, confidence } = usePerception();
 15→
 16→  const { isMobile } = useIsMobile();
 17→  const prefersReducedMotion = usePrefersReducedMotion();
 18→
 19→  const [introVisible, setIntroVisible] = useState(false);
 20→
 21→  // Refs for scroll-driven DOM updates (no re-renders on scroll)
 22→  const scrollIndicatorRef = useRef<HTMLDivElement>(null);
 23→  const introTextRef = useRef<HTMLElement>(null);
 24→  const gradientOverlayRef = useRef<HTMLDivElement>(null);
 25→
 26→  // Hero height based on device - matches HeroReel component
 27→  const heroHeight = isMobile ? '50vh' : '70vh';
 28→  const heroHeightMultiplier = isMobile ? 0.5 : 0.7;
 29→
 30→  // Trigger intro animation on mount
 31→  useEffect(() => {
 32→    const timer = setTimeout(() => setIntroVisible(true), 100);
 33→    return () => clearTimeout(timer);
 34→  }, []);
 35→
 36→  // Listen for chatbot open/close via custom event (replaces MutationObserver)
 37→  useEffect(() => {
 38→    const scrollIndicator = scrollIndicatorRef.current;
 39→    if (!scrollIndicator) return;
 40→
 41→    const observer = new MutationObserver(() => {
 42→      const isOpen = document.body.hasAttribute('data-chatbot-open');
 43→      if (scrollIndicator) {
 44→        scrollIndicator.style.opacity = isOpen ? '0' : scrollIndicator.dataset.scrollOpacity || '1';
 45→        scrollIndicator.style.pointerEvents = isOpen ? 'none' : 'auto';
 46→      }
 47→    });
 48→
 49→    observer.observe(document.body, { attributes: true, attributeFilter: ['data-chatbot-open'] });
 50→    return () => observer.disconnect();
 51→  }, []);
 52→
 53→  // Scroll-driven opacity updates via direct DOM manipulation (no React re-renders)
 54→  useEffect(() => {
 55→    const handleScroll = () => {
 56→      const scrollY = window.scrollY;
 57→
 58→      // Fade out scroll indicator between 0-300px scroll
 59→      const scrollIndicatorOp = Math.max(0, 1 - (scrollY / 300));
 60→      if (scrollIndicatorRef.current) {
 61→        scrollIndicatorRef.current.dataset.scrollOpacity = String(scrollIndicatorOp);
 62→        // Only update DOM if chatbot isn't overriding
 63→        if (!document.body.hasAttribute('data-chatbot-open')) {
 64→          scrollIndicatorRef.current.style.opacity = String(scrollIndicatorOp);
 65→          scrollIndicatorRef.current.style.pointerEvents = scrollIndicatorOp === 0 ? 'none' : 'auto';
 66→        }
 67→      }
 68→
 69→      // Fade out intro text right before it overlaps navigation
 70→      const fadeStart = 600;
 71→      const fadeEnd = 800;
 72→      let introOp = 1;
 73→      if (scrollY > fadeStart) {
 74→        introOp = Math.max(0, 1 - ((scrollY - fadeStart) / (fadeEnd - fadeStart)));
 75→      }
 76→      if (introTextRef.current) {
 77→        introTextRef.current.style.opacity = String(introOp);
 78→      }
 79→
 80→      // Fade gradient overlay for content scrolling under navigation
 81→      const currentHeroHeight = window.innerHeight * heroHeightMultiplier;
 82→      const contentTopPosition = currentHeroHeight - scrollY;
 83→      const navHeight = 200;
 84→      let mainTopOp = 1;
 85→      if (contentTopPosition < navHeight) {
 86→        const fadeDistance = 150;
 87→        const distanceIntoNav = navHeight - contentTopPosition;
 88→        mainTopOp = Math.max(0, 1 - (distanceIntoNav / fadeDistance));
 89→      }
 90→      if (gradientOverlayRef.current) {
 91→        gradientOverlayRef.current.style.opacity = mainTopOp < 1 ? String((1 - mainTopOp) * 0.95) : '0';
 92→      }
 93→    };
 94→
 95→    window.addEventListener('scroll', handleScroll, { passive: true });
 96→    return () => window.removeEventListener('scroll', handleScroll);
 97→  }, [heroHeightMultiplier]);
 98→
 99→  // Find General Reel for hero
100→  const heroProject = projects.find(p => p.slug === 'general-reel');
101→
102→  // Hero statement - authentic, consistent regardless of mode
103→  const heroStatement = "Sixteen years. Feature films, commercials, real-time engines—each frame a problem of light solved in pixels. This is the work.";
104→
105→  // Adapt project order based on visitor archetype
106→  // Only adapts when confidence > 0.5 to avoid premature/unstable reordering
107→  const adaptedProjects = useMemo(() => {
108→    const gridProjects = projects.filter(p => p.slug !== 'general-reel');
109→
110→    // Confidence threshold: don't adapt on weak signal
111→    if (confidence < 0.5 || !archetype) {
112→      return gridProjects;
113→    }
114→
115→    return ProjectAdapter.adaptProjectOrder(gridProjects, archetype);
116→  }, [archetype, confidence]);
117→
118→  return (
119→    <>
120→      {/* Hero Reel - Fixed position, crossfades on scroll, below navigation */}
121→      {heroProject && (
122→        <HeroReel
123→          videoId={heroProject.videoId}
124→          videoHash={heroProject.videoHash}
125→          startTime={heroProject.startTime}
126→          thumbnail={heroProject.thumbnail}
127→        />
128→      )}
129→
130→      {/* Scroll indicator - positioned right below hero reel, hidden when chatbot is open */}
131→      <div
132→        ref={scrollIndicatorRef}
133→        className="fixed left-0 right-0 flex flex-col items-center"
134→        style={{
135→          top: `calc(${heroHeight} - 60px)`,
136→          zIndex: 90,
137→          opacity: 1,
138→          transition: 'opacity 0.3s ease-out'
139→        }}
140→      >
141→        <svg
142→          className="scroll-chevron"
143→          width="24"
144→          height="24"
145→          viewBox="0 0 24 24"
146→          fill="none"
147→          stroke="#8a8a8a"
148→          strokeWidth="2"
149→          strokeLinecap="round"
150→          strokeLinejoin="round"
151→        >
152→          <polyline points="6 9 12 15 18 9" />
153→        </svg>
154→        <p
155→          style={{
156→            color: '#8a8a8a',
157→            fontFamily: 'var(--font-display)',
158→            fontSize: '11px',
159→            fontWeight: 600,
160→            letterSpacing: '0.04em',
161→            textTransform: 'uppercase',
162→            marginTop: '8px'
163→          }}
164→        >
165→          Scroll
166→        </p>
167→      </div>
168→
169→      {/* Gradient fade overlay for content scrolling under navigation */}
170→      <div
171→        ref={gradientOverlayRef}
172→        className="fixed top-0 left-0 right-0 pointer-events-none"
173→        style={{
174→          height: '250px',
175→          background: 'linear-gradient(to bottom, #141414 0%, transparent 100%)',
176→          zIndex: 95,
177→          opacity: 0
178→        }}
179→      />
180→
181→      {/* Main content - starts below viewport, scrolls up */}
182→      <main className="min-h-screen relative" style={{ marginTop: heroHeight, zIndex: 50, backgroundColor: '#141414' }}>
183→        {/* Hero Statement - Isolated quote with generous whitespace (Pentagram style) */}
184→        <section
185→          ref={introTextRef}
186→          className="mx-auto"
187→          style={{
188→            maxWidth: 'var(--max-content-width)',
189→            paddingLeft: 'var(--side-padding)',
190→            paddingRight: 'var(--side-padding)',
191→            paddingTop: 'clamp(102px, 10.2vw + 34px, 170px)',
192→            paddingBottom: 'clamp(102px, 10.2vw + 34px, 170px)',
193→          }}
194→        >
195→          <div style={{ maxWidth: '900px' }}>
196→            {/* Hero Statement - Editorial serif quote style, Pentagram-tight heading */}
197→            <h1
198→              style={{
199→                color: '#a0a0a0',
200→                fontFamily: 'var(--font-lora)',
201→                fontWeight: 400,
202→                fontStyle: 'italic',
203→                fontSize: 'clamp(22px, 3.5vw, 38px)',
204→                lineHeight: 1.2,
205→                letterSpacing: '0.005em',
206→                opacity: introVisible ? 1 : 0,
207→                transform: introVisible ? 'translateY(0)' : `translateY(${isMobile ? 20 : 30}px)`,
208→                transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1), transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1)'
209→              }}
210→            >
211→              {heroStatement}
212→            </h1>
213→          </div>
214→        </section>
215→
216→        {/* Ladder Grid - Golden ratio spacing (excludes hero reel to avoid duplication) */}
217→        <section
218→          className="mx-auto"
219→          style={{
220→            maxWidth: 'var(--max-content-width)',
221→            paddingLeft: 'var(--side-padding)',
222→            paddingRight: 'var(--side-padding)',
223→            paddingBottom: 'var(--space-lg)'    /* 89px - Fibonacci */
224→          }}
225→        >
226→          <LadderGrid projects={adaptedProjects} />
227→        </section>
228→      </main>
229→    </>
230→  );
231→}
232→

 1→import type { NextConfig } from "next";
 2→
 3→const nextConfig: NextConfig = {
 4→  // Generate unique build ID to prevent cache staleness
 5→  generateBuildId: async () => {
 6→    // Use timestamp + git short hash for unique build identification
 7→    return `build-${Date.now()}`;
 8→  },
 9→};
10→
11→export default nextConfig;
12→

  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useCallback } from 'react';
  4→import { usePathname } from 'next/navigation';
  5→import Link from 'next/link';
  6→import dynamic from 'next/dynamic';
  7→
  8→const ChatBot = dynamic(() => import('./ChatBot').then(mod => ({ default: mod.ChatBot })), {
  9→  ssr: false,
 10→});
 11→
 12→const ToolsOverlay = dynamic(() => import('./ToolsOverlay').then(mod => ({ default: mod.ToolsOverlay })), {
 13→  ssr: false,
 14→});
 15→
 16→/**
 17→ * NAVIGATION - Sagmeister-informed sizing
 18→ *
 19→ * Typography hierarchy (responsive clamp):
 20→ * - Logo: 19px mobile → 22px desktop (uppercase, tracked)
 21→ * - Nav links: 18px mobile → 21px desktop (uppercase, tracked)
 22→ * - Generous letter-spacing creates presence
 23→ * - Medium weight (500) for refined look vs Sagmeister's bold (700)
 24→ */
 25→
 26→export function Navigation() {
 27→  const [isChatOpen, setIsChatOpen] = useState(false);
 28→  const [isMenuOpen, setIsMenuOpen] = useState(false);
 29→  const [isToolsOpen, setIsToolsOpen] = useState(false);
 30→  const [scrollProgress, setScrollProgress] = useState(0);
 31→  const pathname = usePathname();
 32→
 33→  // Double-click detection for chatbot icon Easter Egg
 34→  const clickCountRef = useRef(0);
 35→  const clickTimerRef = useRef<NodeJS.Timeout | null>(null);
 36→
 37→  // Double-click detection for chatbot icon
 38→  // Single click: open chatbot
 39→  // Double-click: reveal Tools & Downloads overlay (Easter Egg)
 40→  const handleChatbotClick = useCallback(() => {
 41→    clickCountRef.current++;
 42→
 43→    if (clickCountRef.current === 2) {
 44→      // Double-click detected - open Tools overlay (Easter Egg)
 45→      clickCountRef.current = 0;
 46→      if (clickTimerRef.current) {
 47→        clearTimeout(clickTimerRef.current);
 48→        clickTimerRef.current = null;
 49→      }
 50→      setIsToolsOpen(true);
 51→    } else {
 52→      // Wait for potential second click
 53→      clickTimerRef.current = setTimeout(() => {
 54→        if (clickCountRef.current === 1) {
 55→          // Single click - open chatbot normally
 56→          setIsChatOpen(true);
 57→        }
 58→        clickCountRef.current = 0;
 59→      }, 300);
 60→    }
 61→  }, []);
 62→
 63→  // Cleanup timer on unmount
 64→  useEffect(() => {
 65→    return () => {
 66→      if (clickTimerRef.current) {
 67→        clearTimeout(clickTimerRef.current);
 68→      }
 69→    };
 70→  }, []);
 71→
 72→  // Close menu when route changes
 73→  useEffect(() => {
 74→    setIsMenuOpen(false);
 75→  }, [pathname]);
 76→
 77→  const isHomePage = pathname === '/';
 78→  const isProjectPage = pathname?.startsWith('/projects/');
 79→  // Pages with hero reels need transparent navigation
 80→  const hasHeroReel = isHomePage || isProjectPage;
 81→
 82→  // Active state helper - for aria-current accessibility only (no visual change)
 83→  const isActive = (href: string) => {
 84→    if (href === '/') return isHomePage || isProjectPage;
 85→    return pathname?.startsWith(href);
 86→  };
 87→
 88→  // Track scroll for background opacity - MUST match hero reel fade calculations exactly
 89→  // Navigation background fades in as hero video fades out (synchronized)
 90→  useEffect(() => {
 91→    if (!hasHeroReel) return;
 92→
 93→    const handleScroll = () => {
 94→      const scrollY = window.scrollY;
 95→      const viewportHeight = window.innerHeight;
 96→      const heroHeight = viewportHeight * 0.7;
 97→
 98→      let fadeStartScroll: number;
 99→      let fadeRange: number;
100→
101→      if (isProjectPage) {
102→        // ProjectHeroReel calculation: starts at 30% of hero height
103→        fadeStartScroll = heroHeight * 0.3;
104→        fadeRange = 300;
105→      } else {
106→        // Homepage HeroReel calculation: tied to intro text position
107→        const introPadding = 160;
108→        const textStartPosition = heroHeight + introPadding;
109→        const oneThirdViewport = viewportHeight / 3;
110→        fadeStartScroll = textStartPosition - oneThirdViewport;
111→        fadeRange = 200;
112→      }
113→
114→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
115→      setScrollProgress(progress);
116→    };
117→
118→    // Run immediately to sync initial state with hero reel
119→    handleScroll();
120→
121→    window.addEventListener('scroll', handleScroll, { passive: true });
122→    return () => window.removeEventListener('scroll', handleScroll);
123→  }, [hasHeroReel, isProjectPage]);
124→
125→  // Navigation text color - uses design system variable
126→  const textColor = 'var(--text-primary)';
127→
128→  return (
129→    <>
130→    <nav
131→      className="fixed top-0 left-0 right-0 w-full"
132→      style={{
133→        // Hero reel pages: transparent → solid on scroll (NO CSS transition - scroll IS the animation)
134→        // Other pages: solid background
135→        backgroundColor: hasHeroReel
136→          ? `rgba(20, 20, 20, ${scrollProgress})`
137→          : '#141414',
138→        zIndex: 100,
139→        // Exclude from page transition scale - nav should only fade, not move
140→        viewTransitionName: 'navigation'
141→      }}
142→    >
143→      {/* Pentagram-style: fixed padding, not dramatic scaling */}
144→      <div
145→        className="mx-auto"
146→        style={{
147→          maxWidth: 'var(--max-content-width)',
148→          paddingTop: '28px',
149→          paddingBottom: '20px'
150→        }}
151→      >
152→        {/* Top row: Name and Nav - baseline aligned */}
153→        <div
154→          className="flex items-baseline justify-between"
155→          style={{
156→            paddingLeft: 'var(--side-padding)',
157→            paddingRight: 'var(--side-padding)'
158→          }}
159→        >
160→          {/* Logo - Responsive scaling: 19px at 768px → 22px at 1400px+ */}
161→          <a
162→            href="/"
163→            className="nav-link transition-all duration-400"
164→            style={{
165→              color: textColor,
166→              fontFamily: 'var(--font-display)',
167→              fontWeight: 500,
168→              letterSpacing: '0.16em',
169→              fontSize: 'clamp(19px, 0.5vw + 15px, 22px)',
170→              textTransform: 'uppercase'
171→            }}
172→          >
173→            Joseph Ibrahim
174→          </a>
175→
176→          {/* Desktop Navigation - responsive scaling maintains spacing ratio */}
177→          <div className="hidden md:flex items-baseline" style={{ gap: 'clamp(24px, 2.5vw, 36px)' }}>
178→            <ul className="flex items-baseline" style={{ gap: 'clamp(20px, 2vw, 28px)' }}>
179→              <li>
180→                <Link
181→                  href="/"
182→                  className="nav-link nav-item-shift transition-all duration-400"
183→                  style={{
184→                    color: textColor,
185→                    fontFamily: 'var(--font-display)',
186→                    fontWeight: 500,
187→                    letterSpacing: '0.10em',
188→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
189→                    textTransform: 'uppercase'
190→                  }}
191→                  aria-current={isActive('/') ? 'page' : undefined}
192→                >
193→                  Work
194→                </Link>
195→              </li>
196→              {/* GEN AI - temporarily hidden, page still accessible at /gen-ai */}
197→              <li>
198→                <Link
199→                  href="/photo"
200→                  className="nav-link nav-item-shift transition-all duration-400"
201→                  style={{
202→                    color: textColor,
203→                    fontFamily: 'var(--font-display)',
204→                    fontWeight: 500,
205→                    letterSpacing: '0.10em',
206→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
207→                    textTransform: 'uppercase'
208→                  }}
209→                  aria-current={isActive('/photo') ? 'page' : undefined}
210→                >
211→                  Photo
212→                </Link>
213→              </li>
214→              <li>
215→                <Link
216→                  href="/process"
217→                  className="nav-link nav-item-shift transition-all duration-400"
218→                  style={{
219→                    color: textColor,
220→                    fontFamily: 'var(--font-display)',
221→                    fontWeight: 500,
222→                    letterSpacing: '0.10em',
223→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
224→                    textTransform: 'uppercase'
225→                  }}
226→                  aria-current={isActive('/process') ? 'page' : undefined}
227→                >
228→                  Process
229→                </Link>
230→              </li>
231→              <li>
232→                <Link
233→                  href="/info"
234→                  className="nav-link nav-item-shift transition-all duration-400"
235→                  style={{
236→                    color: textColor,
237→                    fontFamily: 'var(--font-display)',
238→                    fontWeight: 500,
239→                    letterSpacing: '0.10em',
240→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
241→                    textTransform: 'uppercase'
242→                  }}
243→                  aria-current={isActive('/info') ? 'page' : undefined}
244→                >
245→                  About
246→                </Link>
247→              </li>
248→            </ul>
249→
250→            {/* Chat bubble icon - aligned to top of nav text */}
251→            {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
252→            {/* Matches nav-link hover behavior exactly (dims to 40% on hover) */}
253→            <button
254→              onClick={handleChatbotClick}
255→              className="nav-link nav-item-shift transition-all duration-400"
256→              aria-label="Ask about Joe"
257→              style={{
258→                alignSelf: 'flex-start',
259→                marginTop: '5px',
260→                background: 'transparent',
261→                border: 'none',
262→                padding: 0,
263→                cursor: 'pointer'
264→              }}
265→            >
266→              <svg
267→                viewBox="0 0 24 24"
268→                style={{
269→                  width: '17px',
270→                  height: '17px'
271→                }}
272→              >
273→                <path
274→                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
275→                  fill={textColor}
276→                />
277→              </svg>
278→            </button>
279→          </div>
280→
281→          {/* Mobile: Chat + Hamburger - 44px min touch targets */}
282→          {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
283→          <div className="flex md:hidden items-center gap-3">
284→            <button
285→              onClick={handleChatbotClick}
286→              className="nav-link nav-item-shift transition-all duration-400"
287→              aria-label="Ask about Joe"
288→              style={{
289→                minWidth: '44px',
290→                minHeight: '44px',
291→                display: 'flex',
292→                alignItems: 'center',
293→                justifyContent: 'center',
294→                background: 'transparent',
295→                border: 'none',
296→                padding: '12px',
297→                margin: '-8px',
298→                cursor: 'pointer'
299→              }}
300→            >
301→              <svg
302→                width="20"
303→                height="20"
304→                viewBox="0 0 24 24"
305→              >
306→                <path
307→                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
308→                  fill={textColor}
309→                />
310→              </svg>
311→            </button>
312→
313→            {/* Hamburger - 44px min touch target */}
314→            <button
315→              onClick={() => setIsMenuOpen(true)}
316→              className="transition-opacity duration-400 hover:opacity-60 p-3 -m-2"
317→              aria-label="Open menu"
318→              style={{ minWidth: '44px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
319→            >
320→              <svg
321→                width="25"
322→                height="25"
323→                viewBox="0 0 24 24"
324→                fill="none"
325→                stroke={textColor}
326→                strokeWidth="1"
327→                strokeLinecap="round"
328→                className="transition-all duration-400"
329→              >
330→                <line x1="4" y1="8" x2="20" y2="8" />
331→                <line x1="4" y1="16" x2="20" y2="16" />
332→              </svg>
333→            </button>
334→          </div>
335→        </div>
336→
337→      </div>
338→    </nav>
339→
340→    {/* Mobile Menu - Clean overlay */}
341→    {isMenuOpen && (
342→      <div
343→        className="md:hidden fixed inset-0 flex flex-col justify-center items-center"
344→        style={{
345→          backgroundColor: '#141414',
346→          zIndex: 150,
347→          animation: 'fadeIn 350ms ease-out'
348→        }}
349→        onClick={() => setIsMenuOpen(false)}
350→      >
351→        {/* Close button - 44px min touch target */}
352→        <button
353→          onClick={() => setIsMenuOpen(false)}
354→          className="absolute top-9 right-6 p-2 transition-opacity duration-400 hover:opacity-60"
355→          aria-label="Close menu"
356→          style={{ minWidth: '44px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
357→        >
358→          <svg
359→            width="30"
360→            height="30"
361→            viewBox="0 0 24 24"
362→            fill="none"
363→            stroke="var(--text-primary)"
364→            strokeWidth="1"
365→            strokeLinecap="round"
366→          >
367→            <line x1="18" y1="6" x2="6" y2="18" />
368→            <line x1="6" y1="6" x2="18" y2="18" />
369→          </svg>
370→        </button>
371→
372→        {/* Navigation Links - Mobile menu (responsive sizing) */}
373→        <nav onClick={(e) => e.stopPropagation()}>
374→          <ul
375→            className="flex flex-col items-center gap-8"
376→            style={{
377→              fontWeight: 500,
378→              fontFamily: 'var(--font-display)',
379→              letterSpacing: '0.10em',
380→              fontSize: 'clamp(36px, 10vw, 72px)',
381→              textTransform: 'uppercase'
382→            }}
383→          >
384→            <li>
385→              <Link
386→                href="/"
387→                className="block py-3 px-8 transition-opacity duration-400 hover:opacity-60"
388→                style={{
389→                  color: 'var(--text-primary)',
390→                  minHeight: '44px',
