 94→export function ChatBot({ isOpen, onClose }: ChatBotProps) {
 95→  // Get visitor archetype and event recorder from perception system
 96→  const { archetype, confidence, recordEvent } = usePerception();
 97→
 98→  const getInitialMessage = (): string => {
 99→    return "What would you like to know about Joseph's work?";
100→  };
101→
102→  const [messages, setMessages] = useState<Message[]>([
103→    { type: 'bot', text: getInitialMessage() }
104→  ]);
105→  const [inputValue, setInputValue] = useState('');
106→  const [isTyping, setIsTyping] = useState(false);
107→  const [hasConversation, setHasConversation] = useState(false);
108→
109→  // Track timing for response read time calculation
110→  const lastBotResponseTimeRef = useRef<number>(0);
111→  const userMessageCountRef = useRef<number>(0);
112→
113→  const inputRef = useRef<HTMLInputElement>(null);
114→  const messagesEndRef = useRef<HTMLDivElement>(null);
115→  const isMountedRef = useRef(true);
116→  const abortControllerRef = useRef<AbortController | null>(null);
117→
118→  // Track mounted state
119→  useEffect(() => {
120→    isMountedRef.current = true;
121→    return () => {
122→      isMountedRef.current = false;
123→      if (abortControllerRef.current) {
124→        abortControllerRef.current.abort();
125→      }
126→    };
127→  }, []);
128→
129→  // Focus input when chatbot opens
130→  useEffect(() => {
131→    if (isOpen && inputRef.current) {
132→      const focusTimeout = setTimeout(() => {
133→        if (isMountedRef.current && inputRef.current) {
134→          inputRef.current.focus();
135→        }
136→      }, 100);
137→      return () => clearTimeout(focusTimeout);
138→    }
139→  }, [isOpen]);
140→
141→  // Scroll to bottom when new messages arrive
142→  useEffect(() => {
143→    if (messagesEndRef.current) {
144→      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
145→    }
146→  }, [messages, isTyping]);
147→
148→  // Handle escape key to close
149→  useEffect(() => {
150→    const handleEscape = (e: KeyboardEvent) => {
151→      if (e.key === 'Escape' && isOpen) {
152→        onClose();
153→      }
154→    };
155→    document.addEventListener('keydown', handleEscape);
156→    return () => document.removeEventListener('keydown', handleEscape);
157→  }, [isOpen, onClose]);
158→
159→  // Reset on open
160→  useEffect(() => {
161→    if (isOpen) {
162→      setMessages([{ type: 'bot', text: getInitialMessage() }]);
163→      setInputValue('');
164→      setIsTyping(false);
165→      setHasConversation(false);
166→      // Reset chat tracking for perception system
167→      lastBotResponseTimeRef.current = 0;
168→      userMessageCountRef.current = 0;
169→      if (abortControllerRef.current) {
170→        abortControllerRef.current.abort();
171→        abortControllerRef.current = null;
172→      }
173→      document.body.setAttribute('data-chatbot-open', 'true');
174→    } else {
175→      document.body.removeAttribute('data-chatbot-open');
176→    }
177→  }, [isOpen]);
178→
179→  // Send message to AI and stream response
180→  const sendMessage = useCallback(async (query: string) => {
181→    if (!query.trim() || isTyping) return;
182→
183→    // Record response read time if this isn't the first message
184→    if (lastBotResponseTimeRef.current > 0) {
185→      const responseReadTime = Date.now() - lastBotResponseTimeRef.current;
186→      recordEvent({
187→        timestamp: Date.now(),
188→        type: SensorEventType.CHAT_RESPONSE_READ,
189→        data: {
190→          responseReadTime,
191→        },
192→      });
193→    }
194→
195→    // Analyze the message for behavioral signals
196→    const isFollowUp = userMessageCountRef.current > 0;
197→    const messageAnalysis = analyzeChatMessage(query, isFollowUp);
198→    userMessageCountRef.current++;
199→
200→    // Record the chat message event
201→    recordEvent({
202→      timestamp: Date.now(),
203→      type: SensorEventType.CHAT_MESSAGE,
204→      data: {
205→        messageLength: messageAnalysis.messageLength,
206→        wordCount: messageAnalysis.wordCount,
207→        hasTechnicalTerms: messageAnalysis.hasTechnicalTerms,
208→        isFollowUp: messageAnalysis.isFollowUp,
209→        questionCategory: messageAnalysis.questionCategory,
210→      },
211→    });
212→
213→    // Add user message
214→    const userMessage: Message = { type: 'user', text: query };
215→    setMessages(prev => [...prev, userMessage]);
216→    setInputValue('');
217→    setIsTyping(true);
218→    setHasConversation(true);
219→
220→    // Abort any existing request
221→    if (abortControllerRef.current) {
222→      abortControllerRef.current.abort();
223→    }
224→    abortControllerRef.current = new AbortController();
225→
226→    try {
227→      // Get conversation history (excluding the message we just added)
228→      const conversationHistory = messages.map(m => ({
229→        type: m.type,
230→        text: m.text
231→      }));
232→
233→      // Server handles model selection deterministically based on environment
234→      // (Anthropic in production, Ollama locally)
235→      // Visitor context enables archetype-aware response adaptation
236→      const response = await fetch('/api/ai-chat', {
237→        method: 'POST',
238→        headers: { 'Content-Type': 'application/json' },
239→        body: JSON.stringify({
240→          message: query,
241→          messages: conversationHistory,
242→          stream: true,
243→          context: 'portfolio',
244→          // Perception context for invisible adaptation
245→          visitor: {
246→            archetype: archetype ?? 'unknown',
247→            confidence: confidence ?? 0,
248→          },
249→        }),
250→        signal: abortControllerRef.current.signal
251→      });
252→
253→      if (!response.ok) {
254→        throw new Error(`API error: ${response.status}`);
255→      }
256→
257→      // Add empty bot message that we'll stream into
258→      const botMessageIndex = messages.length + 1; // +1 for user message we just added
259→      setMessages(prev => [...prev, { type: 'bot', text: '', isStreaming: true }]);
260→
261→      // Stream the response
262→      const reader = response.body?.getReader();
263→      if (!reader) throw new Error('No response body');
264→
265→      const decoder = new TextDecoder();
266→      let fullText = '';
267→
268→      while (true) {
269→        const { done, value } = await reader.read();
270→        if (done) break;
271→
272→        const chunk = decoder.decode(value, { stream: true });
273→        fullText += chunk;
274→
275→        // Update the bot message with streamed content
