  1→'use client';
  2→
  3→import { useRef, useState, useCallback, useEffect } from 'react';
  4→import type Player from '@vimeo/player';
  5→import { useOptionalVideoThumbnailManager } from './VideoThumbnailManager';
  6→
  7→/**
  8→ * VIDEO THUMBNAIL - Robust Hover-to-Play System
  9→ *
 10→ * Consistency guarantees:
 11→ * 1. Deterministic initialization with timeout (12s max)
 12→ * 2. Retry mechanism if initialization fails
 13→ * 3. Abort pending operations on mouse leave
 14→ * 4. Clean state reset on failures
 15→ * 5. Single active video enforcement via manager
 16→ * 6. AbortController is source of truth for cancellation
 17→ * 7. Manager stops ALL other videos on activation
 18→ */
 19→
 20→// Detect if device supports hover (desktop) vs touch-only (mobile)
 21→function useIsTouchDevice() {
 22→  const [isTouchDevice, setIsTouchDevice] = useState(false);
 23→
 24→  useEffect(() => {
 25→    const mediaQuery = window.matchMedia('(hover: none) and (pointer: coarse)');
 26→    setIsTouchDevice(mediaQuery.matches);
 27→
 28→    const handler = (e: MediaQueryListEvent) => setIsTouchDevice(e.matches);
 29→    mediaQuery.addEventListener('change', handler);
 30→    return () => mediaQuery.removeEventListener('change', handler);
 31→  }, []);
 32→
 33→  return isTouchDevice;
 34→}
 35→
 36→interface VideoThumbnailProps {
 37→  videoId: string;
 38→  videoHash?: string;
 39→  aspectRatio: string;
 40→  startTime?: number;
 41→  isCinematic?: boolean;
 42→  thumbnail?: string;
 43→}
 44→
 45→// Timeout for player initialization (12 seconds - supports slow connections)
 46→const INIT_TIMEOUT_MS = 12000;
 47→
 48→export function VideoThumbnail({
 49→  videoId,
 50→  videoHash,
 51→  startTime,
 52→  isCinematic = false,
 53→  thumbnail
 54→}: VideoThumbnailProps) {
 55→  const containerRef = useRef<HTMLDivElement>(null);
 56→  const playerRef = useRef<Player | null>(null);
 57→  const [isHovering, setIsHovering] = useState(false);
 58→  const [videoVisible, setVideoVisible] = useState(false);
 59→
 60→  // State tracking refs
 61→  const isInitializingRef = useRef(false);
 62→  const isReadyRef = useRef(false);
 63→  const hoveringRef = useRef(false);
 64→  const initFailedRef = useRef(false);
 65→  const abortControllerRef = useRef<AbortController | null>(null);
 66→  const instanceId = useRef(`${videoId}-${Math.random().toString(36).slice(2)}`);
 67→
 68→  // Detect touch device - show full opacity on mobile (no hover)
 69→  const isTouchDevice = useIsTouchDevice();
 70→
 71→  // Get manager if available (works with or without provider)
 72→  const manager = useOptionalVideoThumbnailManager();
 73→
 74→  // Clean destroy of player instance
 75→  const destroyPlayer = useCallback(() => {
 76→    if (playerRef.current) {
 77→      try {
 78→        playerRef.current.destroy();
 79→      } catch {
 80→        // Player may already be destroyed
 81→      }
 82→      playerRef.current = null;
 83→    }
 84→    isReadyRef.current = false;
 85→    isInitializingRef.current = false;
 86→  }, []);
 87→
 88→  // Stop this video - reset to initial state
 89→  // Called by manager when another video becomes active
 90→  const stopVideo = useCallback(() => {
 91→    // Abort any pending operations FIRST (critical for race condition prevention)
 92→    if (abortControllerRef.current) {
 93→      abortControllerRef.current.abort();
 94→      abortControllerRef.current = null;
 95→    }
 96→
 97→    // Reset all state immediately
 98→    hoveringRef.current = false;
 99→    setVideoVisible(false);
100→    setIsHovering(false);
101→
102→    // Try to pause player regardless of ready state
103→    // The player might be in an intermediate state during initialization
104→    if (playerRef.current) {
105→      try {
106→        playerRef.current.pause().catch(() => {});
107→        if (isReadyRef.current) {
108→          playerRef.current.setCurrentTime(startTime ?? 0).catch(() => {});
109→        }
110→      } catch {
111→        // Player in bad state - destroy and allow re-init
112→        destroyPlayer();
113→        initFailedRef.current = false; // Allow retry
114→      }
115→    }
116→  }, [startTime, destroyPlayer]);
117→
118→  // Register with manager on mount
119→  useEffect(() => {
120→    const id = instanceId.current;
121→    if (manager) {
122→      manager.registerVideo(id, stopVideo);
123→      return () => manager.unregisterVideo(id);
124→    }
125→  }, [manager, stopVideo]);
126→
127→  // Cleanup on unmount
128→  useEffect(() => {
129→    return () => {
130→      destroyPlayer();
131→    };
132→  }, [destroyPlayer]);
133→
134→  const initializePlayer = useCallback(async (signal: AbortSignal): Promise<boolean> => {
135→    // Already have a ready player
136→    if (playerRef.current && isReadyRef.current) return true;
137→
138→    // Currently initializing or container missing
139→    if (isInitializingRef.current || !containerRef.current) return false;
140→
141→    // Previous init failed - reset to allow retry
142→    if (initFailedRef.current) {
143→      destroyPlayer();
144→      initFailedRef.current = false;
145→    }
146→
147→    isInitializingRef.current = true;
148→
149→    const baseConfig = {
150→      muted: true,
151→      loop: true,
152→      autoplay: false,
153→      controls: false,
154→      background: true,
155→      responsive: true,
156→      title: false,
157→      byline: false,
158→      portrait: false,
159→      dnt: true,
160→      playsinline: true
161→    };
162→
163→    try {
164→      // Check if aborted before heavy work
165→      if (signal.aborted) {
166→        isInitializingRef.current = false;
167→        return false;
168→      }
169→
170→      // Construct URL with privacy hash and start time
171→      const baseUrl = videoHash
172→        ? `https://vimeo.com/${videoId}/${videoHash}`
173→        : `https://vimeo.com/${videoId}`;
174→      const urlWithTime = startTime ? `${baseUrl}#t=${startTime}s` : baseUrl;
175→
176→      const { default: VimeoPlayer } = await import('@vimeo/player');
177→      if (signal.aborted || !containerRef.current) {
178→        isInitializingRef.current = false;
179→        return false;
180→      }
181→
182→      playerRef.current = new VimeoPlayer(containerRef.current, {
183→        url: urlWithTime as `https://vimeo.com/${string}`,
184→        ...baseConfig
185→      });
186→
187→      // Race between ready() and timeout
188→      const readyPromise = playerRef.current.ready();
189→      const timeoutPromise = new Promise<never>((_, reject) => {
190→        setTimeout(() => reject(new Error('Initialization timeout')), INIT_TIMEOUT_MS);
191→      });
192→
193→      await Promise.race([readyPromise, timeoutPromise]);
194→
195→      // Check if aborted during ready
196→      if (signal.aborted) {
197→        destroyPlayer();
198→        return false;
199→      }
200→
201→      isReadyRef.current = true;
202→      isInitializingRef.current = false;
203→
204→      // Add error event listener for runtime failures
205→      playerRef.current.on('error', (error) => {
206→        console.error('VideoThumbnail: Player error', videoId, error);
207→        // Don't destroy - thumbnail remains visible as fallback
208→      });
209→
210→      return true;
211→
212→    } catch (err) {
213→      console.error('VideoThumbnail: Player init failed', videoId, err);
214→      destroyPlayer();
215→      initFailedRef.current = true;
216→      return false;
217→    }
218→  }, [videoId, videoHash, startTime, destroyPlayer]);
219→
220→  const handleMouseEnter = useCallback(async () => {
221→    const id = instanceId.current;
222→    hoveringRef.current = true;
223→
224→    // Abort any previous pending operations
225→    if (abortControllerRef.current) {
226→      abortControllerRef.current.abort();
227→    }
228→    abortControllerRef.current = new AbortController();
229→    const signal = abortControllerRef.current.signal;
230→
231→    // Tell manager to stop any other active video
232→    if (manager) {
233→      manager.activateVideo(id);
234→    }
235→
236→    setIsHovering(true);
237→
238→    // Initialize and play
239→    const initialized = await initializePlayer(signal);
240→
241→    // Check if we should still play (hover state + abort signal are the source of truth)
242→    if (!hoveringRef.current || signal.aborted) return;
243→
244→    if (initialized && playerRef.current && isReadyRef.current) {
245→      try {
246→        // Final abort check before play
247→        if (signal.aborted) return;
248→
249→        await playerRef.current.play();
250→
251→        // Verify still hovering before showing video layer
252→        if (hoveringRef.current && !signal.aborted) {
253→          setVideoVisible(true);
254→        } else {
255→          // Lost hover during play - pause immediately
256→          playerRef.current.pause().catch(() => {});
257→        }
258→      } catch (err) {
259→        // Play failed - log but don't break, thumbnail is visible
260→        console.warn('VideoThumbnail: Play failed', videoId, err);
261→      }
262→    }
263→  }, [manager, initializePlayer, videoId]);
264→
265→  const handleMouseLeave = useCallback(() => {
266→    hoveringRef.current = false;
267→
268→    if (manager) {
269→      manager.deactivateVideo(instanceId.current);
270→    } else {
271→      stopVideo();
272→    }
273→  }, [manager, stopVideo]);
274→
275→  // Use custom thumbnail if provided, otherwise Vimeo vumbnail
276→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
277→
278→  // Mobile: Static thumbnail only (no video player, no autoplay)
279→  if (isTouchDevice) {
280→    return (
281→      <div
282→        className="relative w-full overflow-hidden"
283→        style={{ aspectRatio: '16/9', borderRadius: '6px' }}
284→      >
285→        <div
286→          className="absolute inset-0 w-full h-full"
287→          style={{
288→            backgroundImage: `url(${thumbnailUrl})`,
289→            backgroundSize: 'cover',
290→            backgroundPosition: 'center',
291→            backgroundColor: '#141414',
292→            borderRadius: '6px'
293→          }}
294→        />
295→      </div>
296→    );
297→  }
298→
299→  // Desktop: Full hover-to-play video functionality
300→  return (
301→    <div
302→      className="relative w-full overflow-hidden"
303→      style={{ aspectRatio: '16/9', borderRadius: '6px' }}
304→      onMouseEnter={handleMouseEnter}
305→      onMouseLeave={handleMouseLeave}
306→    >
307→      {/* Static thumbnail - always visible */}
308→      <div
309→        className="absolute inset-0 w-full h-full"
310→        style={{
311→          backgroundImage: `url(${thumbnailUrl})`,
312→          backgroundSize: 'cover',
313→          backgroundPosition: 'center',
314→          backgroundColor: '#141414',
315→          borderRadius: '6px',
316→          // Light table effect: visible but muted → bright reveal
317→          // Base state: 60% opacity, subtle desaturation - readable but clearly "inactive"
318→          opacity: isHovering ? 1.0 : 0.60,
319→          filter: isHovering ? 'saturate(1) brightness(1)' : 'saturate(0.6) brightness(0.85)',
320→          transition: 'opacity 0.5s cubic-bezier(0.25, 0.1, 0.25, 1), filter 0.5s cubic-bezier(0.25, 0.1, 0.25, 1)'
321→        }}
322→      />
323→
324→      {/* Video layer - fades in when playing */}
