  1→'use client';
  2→
  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import type Player from '@vimeo/player';
  5→import { useIsMobile } from '@/lib/hooks/useIsMobile';
  6→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
  7→
  8→/**
  9→ * HERO REEL - Homepage Autoplay Video
 10→ *
 11→ * Consistency guarantees:
 12→ * 1. Deterministic initialization with timeout (12s max)
 13→ * 2. Clean error handling with fallback to static state
 14→ * 3. Proper cleanup on unmount
 15→ * 4. Scroll-based pause/resume with ref tracking
 16→ * 5. Mobile optimization: static thumbnail only (no video player)
 17→ * 6. Error event listeners for runtime failures
 18→ */
 19→
 20→// Timeout for player initialization (12 seconds - supports slow connections)
 21→const INIT_TIMEOUT_MS = 12000;
 22→
 23→interface HeroReelProps {
 24→  videoId: string;
 25→  videoHash?: string;
 26→  startTime?: number;
 27→  thumbnail?: string;
 28→}
 29→
 30→export function HeroReel({ videoId, videoHash, startTime = 0, thumbnail }: HeroReelProps) {
 31→  const containerRef = useRef<HTMLDivElement>(null);
 32→  const playerRef = useRef<Player | null>(null);
 33→  const isReadyRef = useRef(false);
 34→  const scrolledDownRef = useRef(false);
 35→
 36→  const [scrollProgress, setScrollProgress] = useState(0);
 37→  const [heroRevealed, setHeroRevealed] = useState(false);
 38→
 39→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 40→  const prefersReducedMotion = usePrefersReducedMotion();
 41→
 42→  // Thumbnail URL - use provided thumbnail or fallback to Vimeo vumbnail
 43→  const thumbnailUrl = thumbnail || `https://vumbnail.com/${videoId}.jpg`;
 44→
 45→  // Hero height based on device
 46→  const heroHeight = isMobile ? '50vh' : '70vh';
 47→
 48→  // Clean destroy of player instance
 49→  const destroyPlayer = useCallback(() => {
 50→    if (playerRef.current) {
 51→      try {
 52→        playerRef.current.destroy();
 53→      } catch {
 54→        // Player may already be destroyed
 55→      }
 56→      playerRef.current = null;
 57→    }
 58→    isReadyRef.current = false;
 59→  }, []);
 60→
 61→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 62→  useEffect(() => {
 63→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 64→    return () => clearTimeout(revealTimer);
 65→  }, []);
 66→
 67→  // Initialize Vimeo player with autoplay (desktop only)
 68→  useEffect(() => {
 69→    // Wait for mobile detection to complete before deciding
 70→    if (!isMobileReady) return;
 71→
 72→    // Skip player initialization on mobile - use static thumbnail instead
 73→    if (isMobile) return;
 74→
 75→    if (!containerRef.current) return;
 76→
 77→    const baseConfig = {
 78→      muted: true,
 79→      loop: true,
 80→      autoplay: true,
 81→      controls: false,
 82→      background: true,
 83→      responsive: true,
 84→      title: false,
 85→      byline: false,
 86→      portrait: false,
 87→      dnt: true,
 88→      playsinline: true,
 89→      quality: 'auto',
 90→      speed: true,
 91→    };
 92→
 93→    const baseUrl = videoHash
 94→      ? `https://vimeo.com/${videoId}/${videoHash}`
 95→      : `https://vimeo.com/${videoId}`;
 96→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
 97→
 98→    let isMounted = true;
 99→
100→    const initPlayer = async () => {
101→      try {
102→        const { default: VimeoPlayer } = await import('@vimeo/player');
103→        if (!isMounted || !containerRef.current) return;
104→
105→        playerRef.current = new VimeoPlayer(containerRef.current!, {
106→          url: urlWithTime as `https://vimeo.com/${string}`,
107→          ...baseConfig
108→        });
109→
110→        // Race between ready() and timeout
111→        const readyPromise = playerRef.current.ready();
112→        const timeoutPromise = new Promise<never>((_, reject) => {
113→          setTimeout(() => reject(new Error('HeroReel initialization timeout')), INIT_TIMEOUT_MS);
114→        });
115→
116→        await Promise.race([readyPromise, timeoutPromise]);
117→
118→        if (!isMounted) {
119→          destroyPlayer();
120→          return;
121→        }
122→
123→        isReadyRef.current = true;
124→
125→        // Add error event listener for runtime failures
126→        playerRef.current.on('error', (error) => {
127→          console.error('HeroReel: Player error', videoId, error);
128→          // Don't destroy - let video degrade gracefully to thumbnail
129→        });
130→
131→        // Start playback
132→        await playerRef.current.play().catch(() => {
133→          // Autoplay blocked - video will show loading state
134→        });
135→      } catch (err) {
136→        console.error('HeroReel: Player init failed', videoId, err);
137→        destroyPlayer();
138→      }
139→    };
140→
141→    initPlayer();
142→
143→    return () => {
144→      isMounted = false;
145→      destroyPlayer();
146→    };
147→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
148→
149→  // Track scroll for fade and pause/resume
150→  useEffect(() => {
151→    const handleScroll = () => {
152→      const scrollY = window.scrollY;
153→      const viewportHeight = window.innerHeight;
154→      // Use appropriate hero height multiplier based on device
155→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
156→      const introPadding = 160;
157→      const textStartPosition = heroHeightValue + introPadding;
158→      const oneThirdViewport = viewportHeight / 3;
159→      const fadeStartScroll = textStartPosition - oneThirdViewport;
160→
161→      const fadeRange = 200;
162→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
163→      setScrollProgress(progress);
164→
165→      // Pause/resume with ref tracking for consistency (desktop only)
166→      if (!isMobile) {
167→        const hasScrolledDown = scrollY > 10;
168→
169→        if (hasScrolledDown && !scrolledDownRef.current) {
170→          scrolledDownRef.current = true;
171→          if (playerRef.current && isReadyRef.current) {
172→            playerRef.current.pause().catch(() => {});
173→          }
174→        } else if (!hasScrolledDown && scrolledDownRef.current) {
175→          scrolledDownRef.current = false;
176→          if (playerRef.current && isReadyRef.current) {
177→            playerRef.current.play().catch(() => {});
178→          }
179→        }
180→      }
181→    };
182→
183→    // Run immediately to sync initial state
184→    handleScroll();
185→
186→    window.addEventListener('scroll', handleScroll, { passive: true });
187→    return () => window.removeEventListener('scroll', handleScroll);
188→  }, [isMobile]);
189→
190→  const scrollOpacity = 1 - scrollProgress;
191→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
192→  const heroScale = heroRevealed ? 1 : 1.02;
193→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
194→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
195→
196→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
197→  // This ensures scroll-driven fade is perfectly synchronized with navigation
198→  const heroTransition = heroRevealed
199→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
200→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
201→
202→  return (
203→    <div
204→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
205→      style={{
206→        height: heroHeight,
207→        zIndex: 0,
208→        backgroundColor: '#141414'
209→      }}
210→    >
211→      <div
212→        style={{
213→          width: '100%',
214→          height: '100%',
215→          opacity: heroOpacity,
216→          transform: `scale(${heroScale})`,
217→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
218→          transition: heroTransition,
219→          transformOrigin: 'center center',
220→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
221→        }}
222→      >
223→        {isMobile ? (
224→          // Mobile: Static thumbnail only (no video player)
225→          <div
226→            className="absolute inset-0 w-full h-full"
227→            style={{
228→              backgroundImage: `url(${thumbnailUrl})`,
229→              backgroundSize: 'cover',
230→              backgroundPosition: 'center',
231→              backgroundColor: '#141414',
232→              zIndex: 0
233→            }}
234→          />
235→        ) : (
236→          // Desktop: Vimeo player container
237→          <div
238→            ref={containerRef}
239→            className="absolute inset-0 w-full h-full"
240→            style={{
241→              backgroundColor: '#141414',
242→              zIndex: 0
243→            }}
244→          />
245→        )}
246→      </div>
247→    </div>
248→  );
249→}
