 3→import { useEffect, useRef } from 'react';
 4→import type Player from '@vimeo/player';
 5→
 6→interface EmbeddedVideoPlayerProps {
 7→  videoId: string;
 8→  videoHash?: string; // Privacy hash for private Vimeo videos
 9→}
10→
11→export function EmbeddedVideoPlayer({ videoId, videoHash }: EmbeddedVideoPlayerProps) {
12→  const playerRef = useRef<HTMLDivElement>(null);
13→  const vimeoPlayerRef = useRef<Player | null>(null);
14→
15→  useEffect(() => {
16→    if (!playerRef.current) return;
17→
18→    // Always use URL format for consistent embed behavior across all videos
19→    // URL format works better with Vimeo's embed domain restrictions
20→    const videoUrl = videoHash
21→      ? `https://vimeo.com/${videoId}/${videoHash}`
22→      : `https://vimeo.com/${videoId}`;
23→
24→    let isMounted = true;
25→
26→    const initPlayer = async () => {
27→      const { default: VimeoPlayer } = await import('@vimeo/player');
28→      if (!isMounted || !playerRef.current) return;
29→
30→      vimeoPlayerRef.current = new VimeoPlayer(playerRef.current, {
31→        url: videoUrl as `https://vimeo.com/${string}`,
32→        width: 1280,
33→        responsive: true,
34→        autoplay: false,
35→        color: '6a6a6a',
36→        controls: true
37→      });
38→    };
39→
40→    initPlayer();
41→
42→    return () => {
43→      isMounted = false;
44→      vimeoPlayerRef.current?.destroy();
45→    };
46→  }, [videoId, videoHash]);
47→
48→  return (
49→    <div
50→      ref={playerRef}
51→      className="w-full project-video-player"
52→      style={{
53→        aspectRatio: '16/9',
54→        borderRadius: '6px',
55→        overflow: 'hidden'
56→      }}
57→    />
58→  );
59→}
