11→import { ReactNode, useState, useEffect } from 'react';
12→import { PerceptionProvider, usePerception } from '@/lib/perception/context';
13→import { PerceptionSensor } from '@/components/PerceptionSensor';
14→import { PerceptionIndicator } from '@/components/PerceptionIndicator';
