16→function PerceptionSensorBridge() {
17→  const { recordEvent, sessionId, perceptionState } = usePerception();
18→  const [showDebug, setShowDebug] = useState(false);
19→
20→  // Check for debug mode
21→  useEffect(() => {
22→    if (typeof window !== 'undefined') {
23→      const params = new URLSearchParams(window.location.search);
24→      setShowDebug(params.get('debug') === 'perception');
25→    }
26→  }, []);
27→
28→  return (
29→    <>
30→      <PerceptionSensor recordEvent={recordEvent} sessionId={sessionId} />
31→      <PerceptionIndicator perceptionState={perceptionState} enabled={showDebug} />
32→    </>
33→  );
34→}
35→
36→export function PerceptionLayer({ children }: { children: ReactNode }) {
37→  return (
38→    <PerceptionProvider>
39→      <PerceptionSensorBridge />
40→      {children}
41→    </PerceptionProvider>
42→  );
